for m in ["claude-sonnet-5-5","claude-sonnet-5","claude-haiku-5-5"]:
    for kw in [{}, {"max_tokens":300}]:
        try:
            r=g.chat.completions.create(model=m,messages=[{"role":"user","content":"Say hi"}],**kw)
            print(m,kw,"OK",r.choices[0].message.content)
        except Exception as e: print(m,kw,"ERR",e, getattr(e,'__dict__',''))
E

