import os, assemblyai as aai
aai.settings.api_key=os.environ["ASSEMBLYAI_API_KEY"]
g=aai.LLMGateway()
for m in [x.id for x in g.models.list().data]:
    try:
        r=g.chat.completions.create(model=m,messages=[{"role":"user","content":"Say hi"}],max_tokens=20)
        print(m,"OK")
    except Exception as e: print(m,"ERR",getattr(e,'errors',e))
E

